  Text('1')          .width('90%').height('100%').backgroundColor(Color.Green)          .textAlign(TextAlign.Center).fontSize(30)        Text('2')          .width('90%').height('100%').backgroundColor(Color.Pink)          .textAlign(TextAlign.Center).fontSize(30)"
